const addedCourseChapters = new Set([8, 9, 10, 12, 13]);
for (const [number, lesson] of Object.entries(COURSE_LESSONS)) {
  const n = +number, m = lesson.meta;
  let c = DATA.chapters.find(chapter => chapter.n === n);
  if (!c) {
    c = {n, title:lesson.title, category:lesson.category, practical:{}};
    DATA.chapters.push(c);
  }
  c.sourceCourse = true;
  c.title = lesson.title;
  c.intro = lesson.intro;
  c.sections = lesson.sections.map(s => [...s]);
  c.overview = [lesson.intro, m.focus];
  c.takeaway = m.focus;
  const courseDetails = lesson.sections.slice(8).map(section => [...section]);
  c.deep = addedCourseChapters.has(n) ? [...c.deep, ...courseDetails] : courseDetails;
  c.practical = {...c.practical, why:m.focus, workflow:m.workflow, red:m.red, mistakes:m.mistakes, scenario:m.case[0]};
  c.tools ||= [];
  CHAPTER_GUIDES[n] = {question:lesson.intro, steps:lesson.sections.slice(0,8).map(s=>[...s]), case:[m.case[0],...m.case.slice(1).map(s=>s.split('|'))]};
  const sourceLimit = {
    3: 'This chapter covers U.S. course concepts. Follow your local policies and medical direction for field decisions.',
    5: 'The lesson incorporates the Chapter 5 audiobook as well as the supplied pages and review video.',
    11: 'Use the current instructor skill sheets for equipment sizing and technique.',
    14: 'Use the linked AHA guidance and current instructor skill sheets for resuscitation sequences.'
  }[n];
  const fieldNote = addedCourseChapters.has(n)
    ? 'Follow current instructor skill sheets, medical direction, product instructions, and local protocols for actual care.'
    : '';
  COURSE_NOTES[n] = [
    ...(COURSE_NOTES[n] || []),
    ['Lesson source','', [m.source + '.', sourceLimit, fieldNote].filter(Boolean).join(' ')]
  ];
  REFERENCES_BY_CHAPTER[n] ||= ['ems'];
}
DATA.chapters.sort((a,b)=>a.n-b.n);
